package run.ikaros.password; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/password/devices") public class PasswordDeviceController{private final PasswordDeviceService service;public PasswordDeviceController(PasswordDeviceService s){service=s;}@PostMapping public Mono<PasswordDeviceView> register(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@Valid@RequestBody RegisterDeviceRequest r){return service.register(a,r);}@GetMapping public Flux<PasswordDeviceView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a){return service.list(a);}@PostMapping("/{id}/actions/revoke")public Mono<PasswordDeviceView> revoke(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.revoke(a,id);}@PostMapping("/{id}/actions/sync")public Mono<PasswordDeviceView> sync(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.touchSync(a,id);}}
